<script>
  function switchDetailTab(tabName) {
    const tabStok = document.getElementById('contentStok');
    const tabLokasi = document.getElementById('contentLokasi');
    const tabSinopsis = document.getElementById('contentSinopsis');

    const btnStok = document.getElementById('btnTabStok');
    const btnLokasi = document.getElementById('btnTabLokasi');
    const btnSinopsis = document.getElementById('btnTabSinopsis');

    tabStok.classList.add('hidden');
    tabLokasi.classList.add('hidden');
    tabSinopsis.classList.add('hidden');

    const inactiveClasses = ['text-on-surface-variant', 'font-medium'];
    const activeClasses = ['bg-surface-container-lowest', 'text-primary', 'font-bold', 'shadow-sm'];

    [btnStok, btnLokasi, btnSinopsis].forEach(btn => {
      btn.classList.remove(...activeClasses);
      btn.classList.add(...inactiveClasses);
    });

    if (tabName === 'stok') {
      tabStok.classList.remove('hidden');
      btnStok.classList.add(...activeClasses);
      btnStok.classList.remove(...inactiveClasses);
    } else if (tabName === 'lokasi') {
      tabLokasi.classList.remove('hidden');
      btnLokasi.classList.add(...activeClasses);
      btnLokasi.classList.remove(...inactiveClasses);
    } else if (tabName === 'sinopsis') {
      tabSinopsis.classList.remove('hidden');
      btnSinopsis.classList.add(...activeClasses);
      btnSinopsis.classList.remove(...inactiveClasses);
    }
  }
</script></main><aside class="fixed bottom-0 inset-x-0 z-50 pb-safe bg-surface/95 backdrop-blur-xl shadow-[0_-4px_20px_rgba(30,41,59,0.06)]"><div class="px-gutter-mobile py-space-sm flex items-center justify-between gap-space-md"><div class="flex flex-col justify-center"><span class="font-label-sm text-label-sm text-on-surface-variant uppercase tracking-wider">Status Buku</span><div class="flex items-center gap-1.5"><span class="w-2 h-2 rounded-full bg-tertiary-container animate-pulse"></span><span class="font-title-md text-title-md text-on-tertiary-fixed-variant font-semibold">Tersedia di Rak</span></div></div><div class="flex items-center gap-space-xs flex-1 max-w-xs justify-end"><button class="min-h-[44px] px-space-md py-2.5 rounded-lg bg-surface-container-high text-primary font-title-md text-title-md font-semibold hover:bg-surface-variant active:scale-95 transition-all text-center" type="button">Reservasi</button><button class="min-h-[44px] px-space-lg py-2.5 rounded-lg bg-primary-container text-on-primary font-title-md text-title-md font-semibold hover:bg-primary shadow-[0_4px_14px_rgba(30,41,59,0.2)] active:scale-95 transition-all text-center flex items-center justify-center gap-1.5" type="button"><span class="material-symbols-outlined text-[18px]">menu_book</span><span class="">Pinjam Sekarang</span></button></div></div></aside>
